import*as THREE from'three';import{Component,Port,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{NativeFlexureButton}from'./NativeFlexureButton.js';import{RgbAppearance}from'./RgbAppearance.js';import{addStickers}from'./stickers.js';
function board(host){const s=new THREE.Shape(),r=3.6,dx=r*Math.cos(Math.PI/6),dy=1.8;s.moveTo(-24+dx,17.8);s.lineTo(24-dx,17.8);s.absarc(24,16,r,5*Math.PI/6,5*Math.PI/3,false);s.lineTo(25.8,5.5);s.lineTo(19.5,5.5);s.lineTo(19.5,-5.5);s.lineTo(25.8,-5.5);s.lineTo(25.8,-16+dx);s.absarc(24,-16,r,Math.PI/3,7*Math.PI/6,false);s.lineTo(-24+dx,-17.8);s.absarc(-24,-16,r,11*Math.PI/6,8*Math.PI/3,false);s.lineTo(-25.8,16-dx);s.absarc(-24,16,r,4*Math.PI/3,13*Math.PI/6,false);s.closePath();const pcb=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.8,bevelEnabled:false,curveSegments:48}),materials.plastic(0x246943,{roughness:.88}),[0,0,-18.1],'Scales shaped PCB with real mounting scallops and Grove notch');pcb.userData={role:'physical-pcb',inferred:true};const dark=materials.plastic(0x232824),metal=materials.metal(0xb2b6ab),ceramic=materials.plastic(0xb2a07b),packages=[],leads=[];function ic(x,y,w,h,n,count,pitch){const q=slab(host.body,w,h,1.0,.1,[x,y,-17.2],dark,[],.015);q.name='Scales '+n;packages.push(q);for(const sign of[-1,1])for(let i=0;i<count;i++)leads.push(mesh(host.body,new THREE.BoxGeometry(.7,.24,.18),metal,[x+sign*(w/2+.22),y+(i-(count-1)/2)*pitch,-17.2],'Scales '+n+' actual physical lead'));return q;}const mcu=ic(7,-8,4.4,6.5,'STM32F030F4P6 TSSOP20',10,.65),adc=ic(5,8,3.9,10,'HX711 SOP16',8,1.27),regulator=ic(-7,10,2.5,4.5,'HT7333 regulator envelope',1,1);leads.push(mesh(host.body,new THREE.BoxGeometry(.8,.35,.18),metal,[-7,12.2,-17.2],'Scales regulator third terminal'));const transistor=ic(14,11,1.3,2.9,'S8550 PNP package',1,.95);leads.push(mesh(host.body,new THREE.BoxGeometry(.6,.3,.18),metal,[14,12.4,-17.2],'Scales transistor third terminal'));const passives=[];for(const[i,x,y]of[[1,-10,7],[2,-10,3],[3,14,-9],[4,14,-6],[5,13,5],[6,16,8],[7,7,14],[8,3,14],[9,-3,9],[10,-3,13],[11,0,-10],[12,4,-13],[13,15,0],[14,16,-2],[15,0,12]]){const q=slab(host.body,1.6,.9,.5,.04,[x,y,-17.3],i%2?ceramic:dark,[],.005);q.name='Scales fixed schematic R/C envelope '+i;passives.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.22,.9,.14),metal,[x+sign*.69,y,-17.2],'Scales passive termination');}const keyBody=slab(host.body,6,6,1.1,.25,[-16,-12,-17.3],dark,[],.02);keyBody.name='Scales SW1 actual fixed tactile body';const keyCover=slab(host.body,5.6,5.6,.18,.25,[-16,-12,-16.2],metal,[],.005);keyCover.name='Scales SW1 metal cover';const plunger=mesh(host.body,new THREE.CylinderGeometry(1.1,1.1,.85,32).rotateX(Math.PI/2),dark,[-16,-12,-15.59],'Scales SW1 recessed retained plunger');const led=slab(host.body,3.5,3.5,.8,.1,[-21,0,-17.3],materials.plastic(0xe0e4d6),[],.01);led.name='Scales actual SK6812 RGB physical package';for(const x of[-22.65,-19.35])for(const y of[-1.1,1.1])mesh(host.body,new THREE.BoxGeometry(.45,.7,.15),metal,[x,y,-17.15],'Scales RGB physical solder terminal');const debugPads=[];for(let i=0;i<5;i++)debugPads.push(mesh(host.body,new THREE.CylinderGeometry(.5,.5,.035,24).rotateX(Math.PI/2),materials.metal(0xbda151),[-8+i*2.54,-5,-17.28],'Scales J2 fixed SWD solder pad'));return{pcb,packages,leads,mcu,adc,regulator,transistor,passives,keyBody,keyCover,plunger,led,debugPads};}
function support(host){const metal=materials.metal(0xb8bebc,{roughness:.33}),black=materials.plastic(0x202523,{roughness:.8}),can=mesh(host.body,new THREE.CylinderGeometry(13.65,13.65,6.53,96).rotateX(Math.PI/2),metal,[0,0,6.015],'Scales actual fixed metal load-cell support envelope');can.userData={role:'physical-load-cell',inferred:true,scope:'Fixed external metal can and support only;no force,deflection,weight or strain physics'};const stud=mesh(host.body,new THREE.CylinderGeometry(3.8,3.8,4.5,48).rotateX(Math.PI/2),metal,[0,0,10.4],'Scales fixed load-cell/platform retained central support');const gland=mesh(host.body,new THREE.CylinderGeometry(2.8,2.8,3.1,6).rotateZ(Math.PI/2),metal,[14.9,0,5.5],'Scales actual side metal cable gland hex nut');const sleeve=mesh(host.body,new THREE.CylinderGeometry(1.8,1.8,1.8,40).rotateZ(Math.PI/2),black,[17.2,0,5.5],'Scales cable gland fixed rubber sleeve');const curve=new THREE.CatmullRomCurve3([[17.6,0,5.5],[20.4,0,3.8],[20,0,-.5],[16.8,0,-5.3],[14.4,0,-11.8]].map(p=>new THREE.Vector3(...p))),cable=mesh(host.body,new THREE.TubeGeometry(curve,64,1.15,16,false),black,[0,0,0],'Scales actual retained black load-cell cable');const end=mesh(host.body,new THREE.SphereGeometry(1.15,24,16),black,[14.4,0,-11.8],'Scales cable retained base entry');return{can,stud,gland,sleeve,cable,end};}
function grove(host){const frame=new THREE.Group();frame.name='Scales physical red HY2.0-4P';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.right);host.body.add(frame);const plastic=materials.plastic(spec.grove.color),metal=materials.metal(0xb6b49c),box=(s,p,n,m=plastic)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'Scales Grove '+n);for(const sign of[-1,1]){box([.65,5.2,6.3],[sign*4.675,0,-3.15],'side rail');box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'guide');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'locking shoulder');}box([8.7,.65,6.3],[0,-2.275,-3.15],'floor');box([8.7,4.55,.65],[0,.325,-5.975],'recessed dielectric rear wall');box([4.8,.45,2.3],[0,2.375,-4.5],'short locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],'real contact '+(i+1),metal));box([.42,1.2,.42],[(i-1.5)*2,-2.6,-5.8],'solder tail '+(i+1),metal);}const port=host.add(new Port({id:'grove',label:'PORT.A · I2C',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('right'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'SDA',color:'yellow'},{n:4,name:'SCL',color:'white'}],meta:{role:'visual-connector',face:'right',scope:'Four physical contacts,cable pose and documented labels only;no I2C,weight,electrical,power or firmware behavior'}}));return{frame,contacts,port};}
export function buildScales(host){const parts=addCadParts(host,data,{shell:materials.plastic(0x505653,{roughness:.83})}),electronics=board(host),loadCell=support(host),input=grove(host),shell=parts['Scales complete native base and pedestal'],tare=host.add(new NativeFlexureButton(shell));const lens=slab(host.body,...spec.rgb.lensMm,.8,spec.rgb.position,materials.plastic(0xd9e2d9,{roughness:.52}),[],.01);lens.name='Scales actual recessed RGB light-guide strip';lens.userData={role:'physical-light-guide',couplingInferred:true};const rgb=host.add(new RgbAppearance(lens,spec.rgb.position)),sensor=host.add(new Component({id:'sensor',label:'Scales fixed load-cell appearance anchor',position:spec.sensor.position,meta:{role:'visual-anchor',scope:'Passive physical support anchor only;no mass,weight,strain,deflection,load,zero,calibration,electrical or firmware values'}}));const film=slab(host.body,...spec.labels.back.size,.04,.15,spec.labels.back.position,materials.plastic(0xe2e3de),[],0);film.rotation.z=spec.labels.back.rotation;film.name='Scales independent physical rear adhesive label film';film.userData={role:'physical-label-substrate',face:'back'};const fixings=[];for(const x of[-14,14])fixings.push(screw(host.body,[x,16,-20.45],'back',1.3));host.scalesAssembly={parts,shell,electronics,loadCell,input,tare,rgb,lens,sensor,film,fixings};host.unitStickers=addStickers(host);}
